$ErrorActionPreference = 'Stop'
$Root = (Get-Location).Path

if (-not (Test-Path (Join-Path $Root 'Start-Miniverse.ps1'))) {
    throw "Run this from control_plane_v2. Current path: $Root"
}

[IO.File]::WriteAllBytes((Join-Path $Root 'Start-Miniverse.ps1'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $Root 'Start-AHOS-OnLogin.ps1'), [Convert]::FromBase64String(''))

[void][scriptblock]::Create((Get-Content (Join-Path $Root 'Start-Miniverse.ps1') -Raw))
[void][scriptblock]::Create((Get-Content (Join-Path $Root 'Start-AHOS-OnLogin.ps1') -Raw))

Write-Host 'PowerShell syntax: PASS'

git add Start-Miniverse.ps1 Start-AHOS-OnLogin.ps1
git diff --cached --quiet
if ($LASTEXITCODE -ne 0) {
    git -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "fix: make AHOS Windows startup tolerant and hidden"
    if ($LASTEXITCODE -ne 0) { throw 'git commit failed.' }
    git push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw 'git push failed.' }
    Write-Host 'Git commit/push: PASS'
}

Write-Host ''
Write-Host '=== AUTOSTART PATCH COMPLETE ==='
Write-Host 'Current running worker/autopilot were not stopped.'
Write-Host 'No OpenAI API calls were made.'
